-- #1694 Part A: release request 진실 원천을 backend로 이전(h2 test dialect — VARCHAR(64) sha, compact form).
CREATE TABLE datapack_release_request (approval_id VARCHAR(255) NOT NULL PRIMARY KEY, candidate_id VARCHAR(255) NOT NULL, scope_id VARCHAR(255) NOT NULL, target_channel VARCHAR(32) NOT NULL, build_spec_sha256 VARCHAR(64) NOT NULL, source_snapshot_set_hash VARCHAR(64) NOT NULL, approved_ledger_hash VARCHAR(64) NOT NULL, requested_by VARCHAR(255) NOT NULL, approved_by VARCHAR(255), status VARCHAR(32) NOT NULL, dispatch_idempotency_key VARCHAR(255), workflow_run_url VARCHAR(1024), created_at TIMESTAMP NOT NULL, approved_at TIMESTAMP, updated_at TIMESTAMP NOT NULL, CONSTRAINT chk_datapack_release_request_target_channel CHECK (target_channel IN ('dev', 'staging', 'production')));
